import './neon-menu.scss';
import { createElement, getPageDirection, } from '../shared/dom-manipulation';
import { NeonPopover } from '../neon-popover/neon-popover';
export class NeonMenu extends NeonPopover {
    static get observedAttributes() {
        const attributes = super.observedAttributes.concat([
            'id',
            'data-show-header-text',
            'data-popper-max-height'
        ]);
        return attributes;
    }
    static get inputProperties() {
        return [
            'options',
            'context'
        ];
    }
    static get requiredSlots() {
        return [
            { slot: 'popper-trigger', tag: 'div' }
        ];
    }
    constructor() {
        super();
        this.widgetTag = 'neon-menu';
        this.nestedPopperDefaultPlacement = getPageDirection() === 'rtl' ? 'left-start' : 'right-start';
        this.isUsesLabel = false;
        this.isRequiresLabelText = false;
    }
    validateInputs() {
        super.validateInputs();
        if (this.getAttribute('data-header-text') == null) {
            console.error(`You must include the attribute data-header-text for ${this.tagName} with id: ${this.getAttribute('id')}`);
        }
        if (this.options == null) {
            console.error(`You must include a the options property for ${this.tagName} with id: ${this.getAttribute('id')}`);
        }
    }
    isDisabledItem(item) {
        if (item.isDisabled != null) {
            return item.isDisabled(item);
        }
        else {
            return false;
        }
    }
    renderPopperElement() {
        if (this.options == null) {
            console.error('There are no options for the neon-menu to render');
            return createElement('div');
        }
        return this.renderPopperFromMenuItems(this.options);
    }
    renderPopperFromMenuItems(menuOptions) {
        return createElement('neon-2_20_1-item-picker', {
            attrs: {
                id: this.getAttribute('id') + '-popper',
                'data-item-tooltip-placement': (this.getAttribute('data-button-tooltip-placement') || 'top'),
                'data-item-popper-placement': this.getAttribute('data-descendant-popper-placement'),
                'data-header-text': this.getAttribute('data-header-text') || '',
                'data-show-header-text': String(this.getAttribute('data-show-header-text') !== 'false'),
                'data-popper-max-height': this.getAttribute('data-popper-max-height') || undefined,
                'data-item-menu-size': this.getAttribute('data-restrict-popper-width') === 'true' ? 'auto' : undefined,
                'data-use-arrow': 'false',
                'data-control-type': 'popper',
            },
            properties: {
                menuOptions: menuOptions,
                context: this.context
            }
        });
    }
    isArrowShowing() {
        return false;
    }
}
